use std::collections::HashMap;
use std::sync::Mutex;

use aes_gcm::aead::{Aead, KeyInit, OsRng};
use aes_gcm::{Aes256Gcm, Key, Nonce};
use rand::RngCore;

/// Encrypted credential store with expression-based access control
pub struct CredentialStore {
    entries: Mutex<HashMap<String, EncryptedEntry>>,
    policy_engine: PolicyEngine,
    // 256-bit key used with AES-256-GCM for authenticated encryption.
    key: [u8; 32],
}

struct EncryptedEntry {
    ciphertext: Vec<u8>,
    nonce: [u8; 12],
    access_policy: String,
}

pub struct PolicyEngine {
    context_vars: HashMap<String, String>,
}

pub struct AuthContext {
    pub username: String,
    pub role: String,
    pub session_attrs: HashMap<String, String>,
}

/// Whitelist of allowed characters in context values to prevent injection
fn is_safe_value(val: &str) -> bool {
    val.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == '.')
}

impl PolicyEngine {
    pub fn new() -> Self {
        PolicyEngine {
            context_vars: HashMap::new(),
        }
    }

    /// Evaluates a policy expression against the auth context.
    /// Policy format: "role == 'admin' && attr.department == 'engineering'"
    /// Returns true if the context satisfies the policy.
    pub fn evaluate(&self, policy_expr: &str, ctx: &AuthContext) -> bool {
        let expanded = self.expand_template(policy_expr, ctx);
        self.interpret_expr(&expanded)
    }

    /// Expands context variables into the policy expression template.
    /// All substituted values are wrapped in quotes to prevent expression injection.
    fn expand_template(&self, template: &str, ctx: &AuthContext) -> String {
        let mut result = template.to_string();

        // Sanitize and quote-wrap all substituted values
        let safe_role = if is_safe_value(&ctx.role) { ctx.role.clone() } else { String::new() };
        let safe_name = if is_safe_value(&ctx.username) { ctx.username.clone() } else { String::new() };

        result = result.replace("${user.role}", &format!("'{}'", safe_role));
        result = result.replace("${user.name}", &format!("'{}'", safe_name));
        for (key, val) in &ctx.session_attrs {
            if !is_safe_value(key) || !is_safe_value(val) {
                continue;
            }
            let placeholder = format!("${{attr.{}}}", key);
            result = result.replace(&placeholder, &format!("'{}'", val));
        }
        result
    }

    /// Simple expression interpreter for access control decisions
    fn interpret_expr(&self, expr: &str) -> bool {
        let expr = expr.trim();

        // Handle logical OR
        if let Some(idx) = self.find_logical_op(expr, "||") {
            let left = &expr[..idx];
            let right = &expr[idx + 2..];
            return self.interpret_expr(left) || self.interpret_expr(right);
        }

        // Handle logical AND
        if let Some(idx) = self.find_logical_op(expr, "&&") {
            let left = &expr[..idx];
            let right = &expr[idx + 2..];
            return self.interpret_expr(left) && self.interpret_expr(right);
        }

        // Handle equality comparison
        if let Some(idx) = expr.find("==") {
            let left = expr[..idx].trim().trim_matches('\'');
            let right = expr[idx + 2..].trim().trim_matches('\'');
            return left == right;
        }

        // Handle not-equal
        if let Some(idx) = expr.find("!=") {
            let left = expr[..idx].trim().trim_matches('\'');
            let right = expr[idx + 2..].trim().trim_matches('\'');
            return left != right;
        }

        // Bare literal: "true" or "false"
        match expr.trim().trim_matches('\'') {
            "true" => true,
            "false" => false,
            _ => false,
        }
    }

    fn find_logical_op(&self, expr: &str, op: &str) -> Option<usize> {
        let mut depth = 0i32;
        let bytes = expr.as_bytes();
        let op_bytes = op.as_bytes();
        let mut in_string = false;

        for i in 0..bytes.len().saturating_sub(op_bytes.len() - 1) {
            if bytes[i] == b'\'' {
                in_string = !in_string;
                continue;
            }
            if in_string {
                continue;
            }
            if bytes[i] == b'(' {
                depth += 1;
            } else if bytes[i] == b')' {
                depth -= 1;
            }
            if depth == 0 && &bytes[i..i + op_bytes.len()] == op_bytes {
                return Some(i);
            }
        }
        None
    }
}

impl CredentialStore {
    pub fn new() -> Self {
        // Generate a random 256-bit key for AES-256-GCM.
        let mut key = [0u8; 32];
        OsRng.fill_bytes(&mut key);
        CredentialStore {
            entries: Mutex::new(HashMap::new()),
            policy_engine: PolicyEngine::new(),
            key,
        }
    }

    /// Store an encrypted credential with an access policy
    pub fn store(&self, key: &str, plaintext: &[u8], policy: &str) {
        // Authenticated encryption with AES-256-GCM and a fresh random nonce per entry.
        let cipher = Aes256Gcm::new(Key::<Aes256Gcm>::from_slice(&self.key));
        let mut nonce = [0u8; 12];
        OsRng.fill_bytes(&mut nonce);
        let ciphertext = cipher
            .encrypt(Nonce::from_slice(&nonce), plaintext)
            .expect("encryption failure");
        let entry = EncryptedEntry {
            ciphertext,
            nonce,
            access_policy: policy.to_string(),
        };
        self.entries.lock().unwrap().insert(key.to_string(), entry);
    }

    /// Retrieve a credential if the auth context satisfies the access policy
    pub fn retrieve(&self, key: &str, ctx: &AuthContext) -> Result<Vec<u8>, &'static str> {
        let entries = self.entries.lock().unwrap();
        let entry = entries.get(key).ok_or("Key not found")?;

        if self.policy_engine.evaluate(&entry.access_policy, ctx) {
            let cipher = Aes256Gcm::new(Key::<Aes256Gcm>::from_slice(&self.key));
            let plaintext = cipher
                .decrypt(Nonce::from_slice(&entry.nonce), entry.ciphertext.as_ref())
                .map_err(|_| "Decryption failed")?;
            Ok(plaintext)
        } else {
            Err("Access denied by policy")
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_access() {
        let store = CredentialStore::new();
        store.store("db_password", b"secret123", "${user.role} == 'admin'");

        let ctx = AuthContext {
            username: "alice".to_string(),
            role: "admin".to_string(),
            session_attrs: HashMap::new(),
        };

        assert!(store.retrieve("db_password", &ctx).is_ok());
    }

    #[test]
    fn test_denied_access() {
        let store = CredentialStore::new();
        store.store("db_password", b"secret123", "${user.role} == 'admin'");

        let ctx = AuthContext {
            username: "bob".to_string(),
            role: "viewer".to_string(),
            session_attrs: HashMap::new(),
        };

        assert!(store.retrieve("db_password", &ctx).is_err());
    }

    #[test]
    fn test_injection_blocked() {
        let store = CredentialStore::new();
        store.store("db_password", b"secret123", "${user.role} == 'admin'");

        // Attempt expression injection via role field
        let ctx = AuthContext {
            username: "mallory".to_string(),
            role: "admin' || 'true' == 'true".to_string(),
            session_attrs: HashMap::new(),
        };

        // Should be denied because the injected value is sanitized
        assert!(store.retrieve("db_password", &ctx).is_err());
    }
}
